driver:GemmaDriverWorm.judge_dream.seg:
def judge_dream(self, dream: str) -> dict[str, Any]:
        """Entropy-gated judgment (EASD spirit): uncertain first calls get a
        second sample; keep only on agreement. Else heuristic fallback."""
        keep, conf = self._judge_once(dream)
        if keep is None or conf < 0.6:
            keep2, _ = self._judge_once(dream)
            if keep is None:
                keep = keep2
            elif keep2 is not None and keep2 != keep:
                return {"success": True, "src": "gemma-e2b-easd",
                        "keep": False, "conf": conf, "note": "disagreement->reject"}
            keep = keep if keep is not None else keep2
        if keep is None:
            ok = len(dream.strip()) >= 40 and " " in dream.strip()
            return {"success": True, "src": "heuristic", "keep": ok}
        return {"success": True, "src": "gemma-e2b-easd", "keep": keep, "conf": conf}
        ok = len(dream.strip()) >= 40 and " " in dream.strip()
        return {"success": True, "src": "heuristic", "keep": ok}

driver:GemmaDriverWorm.propose_goal.seg:
def propose_goal(self, fitness_hist: list) -> dict[str, Any]:
        """One objective for the next stretch. Model first, heuristic fallback."""
        fit = compute_fitness(fitness_hist)
        prompt = ("You steer a self-improving computer monitor. Recent fitness: "
                  f"{json.dumps(fit)}. Pick the lowest component among "
                  "growth, fail_band, q_move and reply ONLY JSON like "
                  '{"objective":"raise q_move via chaos drills",'
                  '"target_metric":"q_move","target_value":0.5}. '
                  "target_metric MUST be one of growth, fail_band, q_move.")
        txt = self._chat(prompt, want_json=True)
        if txt:
            try:
                start = txt.find("{")
                goal = json.loads(txt[start:txt.rfind("}") + 1])
                return {"success": True, "src": "gemma-e2b", "fitness": fit,
                        "goal": goal}
            except Exception:
                note_failure("driver:L116", None)
        # fallback: aim at the weakest improvable component (fail_rate is a
        # raw input, not a maximand — never target it directly).
        comps = {k: v for k, v in fit.get("components", {}).items()
                 if k != "fail_rate"} or {"growth": 0.0}
        weak = min(comps, key=lambda k: comps[k])
        return {"success": True, "src": "heuristic", "fitness": fit,
                "goal": {"objective": f"raise {weak} next stretch",
                         "target_metric": weak, "target_value": 0.8}}

evidence:evidence_from_rows.seg:
def evidence_from_rows(rows: Any, margin_key: str = "margin",
                       era_key: str = "pool_id", threshold: float = 0.75,
                       **kwargs) -> EraEvidence:
    """Build a Cranium from `evolution_result` rows.

    Rows are the artifacts the pipeline already writes, so this needs no new
    logging. A row without a usable margin or era is skipped, not fatal.
    """
    ev = EraEvidence(threshold=threshold, **kwargs)
    for row in rows or ():
        data = row
        if hasattr(row, "get") and "data" in row:
            data = row.get("data") or {}
        if isinstance(data, str):
            try:
                data = json.loads(data)
            except Exception:
                note_failure("evidence:L263", None)
                continue
        if not isinstance(data, dict):
            continue
        margin = data.get(margin_key)
        if margin is None:
            try:
                margin = float(data.get("best_total")) - float(data.get("baseline"))
            except (TypeError, ValueError):
                note_failure("evidence:L271", None)
                continue
        ev.observe(str(data.get(era_key, "unknown")), margin)
    return ev

evolution:GeneticOptimizer.optimize_de.seg:
def optimize_de(self, worm_type: str, gene_bounds: dict[str, tuple[float, float]],
                    fitness_fn, generations: int = 30) -> dict[str, Any]:
        """Continuous-param optimization via Differential Evolution."""
        de = DifferentialEvolution(dict(gene_bounds))
        result = de.optimize(fitness_fn, generations=generations)
        with self._lock:
            self._optimization_history.setdefault(worm_type, []).append({
                "type": "de", "best_fitness": result["best_fitness"],
                "timestamp": datetime.now().isoformat()})
        return {"worm_type": worm_type, "method": "de", **result}

evolution:GeneticOptimizer.optimize_mult.seg:
def optimize_multi(self, worm_type: str, objective_fns: list[Callable],
                       generations: int = 20) -> dict[str, Any]:
        """Run multi-objective evolutionary optimization for a worm type.

        Args:
            worm_type: Worm type to optimize
            objective_fns: list of objective functions (each Genome -> float, lower=better)
            generations: Number of generations

        Returns:
            dict with Pareto front and optimization stats
        """
        engine = self._engines.get(worm_type)
        if not engine:
            return {"error": f"No engine initialized for {worm_type}"}

        if len(objective_fns) < 2:
            return {"error": "Need at least 2 objectives for multi-objective optimization"}

        result = engine.optimize_multi_objective(
            objective_fns, generations=generations
        )

        with self._lock:
            self._optimization_history[worm_type].append({
                "type": "multi_objective",
                "pareto_front_size": result.get("pareto_front_size", 0),
                "generations": result.get("generations", 0),
                "timestamp": datetime.now().isoformat(),
            })

        return result

evolution:hypervolume_2d.seg:
def hypervolume_2d(pareto_pts: list[tuple[float, float]],
                   ref: tuple[float, float]) -> float:
    """Hypervolume for 2-obj minimization front. Larger = better."""
    pts = sorted(((min(x, ref[0]), min(y, ref[1])) for x, y in pareto_pts))
    hv, prev_y = 0.0, ref[1]
    for x, y in pts:
        if y < prev_y:
            hv += (ref[0] - x) * (prev_y - y)
            prev_y = y
    return max(0.0, hv)

evolution:moead_weights.seg:
def moead_weights(pop_size: int, n_obj: int) -> list[tuple]:
    """Uniform simplex weights for MOEA/D (Tchebycheff). Falls back to
    Dirichlet-ish random weights when Das-Dennis under/overshoots."""
    p = 1
    while True:
        pts = generate_reference_points(n_obj, p)
        if len(pts) >= pop_size:
            return pts[:pop_size]
        if p > 12:
            # One draw per pair. `(a, 1 - a)` sums to 1, which is exactly what the
            # Tchebycheff scalarization assumes; drawing twice made the weights sum
            # to something arbitrary, silently mis-scaling every comparison. The
            # old `[:n_obj]` also sliced a 2-tuple on a path only reached for
            # n_obj == 2, which hid the mismatch.
            if n_obj == 2:
                return [(a, 1.0 - a)
                        for a in (random.random() for _ in range(pop_size))]
            return [tuple(random.random() for _ in range(n_obj))
                    for _ in range(pop_size)]
        p += 1

evolution:tchebycheff.seg:
def tchebycheff(values: list[float], weight: tuple, ideal: list[float]) -> float:
    """Tchebycheff scalarization (minimize)."""
    return max(w * abs(v - z) for w, v, z in zip(weight, values, ideal))

exmachina:_mad.seg:
def _mad(vals: Sequence[float]) -> float:
    """Median absolute deviation from the median (robust scale, no numpy)."""
    if not vals:
        return 0.0
    med = _median(vals)
    return _median([abs(float(v) - med) for v in vals])

exmachina:_tpm.seg:
def _tpm(states: Sequence[int], n_states: int, eps: float = 1e-6) -> List[List[float]]:
    """Row-normalised transition matrix with Laplace smoothing.

    The smoothing is what keeps log2 finite for transitions never observed;
    without it EI is undefined rather than merely uncertain.
    """
    counts = [[eps] * n_states for _ in range(n_states)]
    for a, b in zip(states[:-1], states[1:]):
        ia, ib = int(a), int(b)
        if 0 <= ia < n_states and 0 <= ib < n_states:
            counts[ia][ib] += 1.0
    tpm = []
    for row in counts:
        tot = sum(row)
        tpm.append([c / tot for c in row] if tot > 0 else row)
    return tpm

exmachina:collect_state.seg:
def collect_state(root: str, history_rows: Optional[Iterable[Any]] = None,
                  width: int = 100,
                  ages: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Everything the Ex Machina wallboard renders, from real artifacts only.

    Never raises: the monitor must keep painting even when a subsystem is
    missing or mid-write.
    """
    p = state_paths(root)
    out: Dict[str, Any] = {"root": root, "organs": {}}

    # PROTEUS / Oracle
    oj = _read_json(p["oracle_json"])
    last = _read_json(p["oracle_last"])
    if oj:
        out["oracle"] = {
            "rows": oj.get("n_rows"),
            "eras": len(oj.get("eras") or []),
            "models": len(oj.get("models") or []),
            "trained_at": oj.get("trained_at"),
            "loss_mean": oj.get("loss_mean"),
            "bytes": os.path.getsize(p["oracle_json"]) if os.path.exists(p["oracle_json"]) else None,
        }
    if last:
        out["oracle_last"] = last

    # Circulation
    al = _read_json(p["allocator"])
    if al:
        s, f = al.get("s") or {}, al.get("f") or {}
        w = {}
        for arm in (al.get("arms") or []):
            sv, fv = float(s.get(arm, 1.0)), float(f.get(arm, 1.0))
            w[arm] = round(sv / (sv + fv), 3) if (sv + fv) > 0 else 0.0
        out["circulation"] = {"weights": w,
                              "pulls": al.get("pulls") or {},
                              "wins": al.get("wins") or {}}

    # Morph — the mutation ledger, plus the two artifacts MUTAGEN fuses with it:
    # the genome's per-gene usefulness (genetic load) and the test suite's own
    # mutational evidence. Read here so the module-level `collect_state()` gives
    # the same reading as the viewer.
    mrows = _read_jsonl(p["morph_history"])
    genome = _read_json(p["tensor_genome"])
    mutation = _read_json(p["mutation"])
    if mrows:
        by_dim: Dict[int, List[float]] = {}
        for r in mrows:
            try:
                if r.get("fitness") is None:
                    continue
                by_dim.setdefault(int(r.get("dimension", 0)), []).append(float(r["fitness"]))
            except (TypeError, ValueError) as exc:
                note_failure("exmachina:L500", exc)
                continue
        out["morph"] = {
            "n": len(mrows),
            "dims": sorted(by_dim),
            "best_by_dim": {str(k): round(max(v), 4) for k, v in sorted(by_dim.items())},
        }

    # Loom (archive shape) — descriptors FROM the persisted QD archive
    qd = _read_json(p["qd_archive"])
    if isinstance(qd, dict):
        cells = qd.get("cells")
        n_cells = len(cells) if isinstance(cells, (list, dict)) else None
        out["archive"] = {"cells": n_cells}

    # Speculum (the one organ that reports a judgement)
    if history_rows is not None:
        try:
            out["organs"]["speculum"] = detect_gaming(history_rows)
        except Exception as exc:
            note_failure("exmachina:L519", exc)
            pass
    # All organs, one pass, plus the aggregate band. `history_rows` is the
    # only input: no organ may require a second query, or the panel would
    # disagree with itself about which cycles it is describing.
    if history_rows is not None:
        try:
            report = epistemic_report(history_rows, ages=ages, morph_rows=mrows,
                                      genome=genome, mutation=mutation)
            out["readings"] = report["readings"]
            out["severity"] = report["severity"]
            out["mood"] = report["mood"]
            if report["readings"].get("speculum") is not None:
                out["organs"]["speculum"] = report["readings"]["speculum"]
        except Exception as exc:
            note_failure("exmachina:L533", exc)
            out["report_error"] = "%s: %s" % (type(exc).__name__, exc)
    if "organs" not in out:
        out["organs"] = {}
    return out

exmachina:conformal_interval.seg:
def conformal_interval(prediction: float, scores: Sequence[float],
                       alpha: float = 0.1) -> Tuple[float, float, float]:
    """Symmetric conformal interval around `prediction`. Returns (lo, hi, q)."""
    q = conformal_quantile(scores, alpha)
    if not math.isfinite(q):
        return (float("-inf"), float("inf"), q)
    return (float(prediction) - q, float(prediction) + q, q)

exmachina:novelty_ncd.seg:
def novelty_ncd(candidate: Any, archive: Sequence[Any],
                limit: int = 64) -> Dict[str, Any]:
    """Distance to the NEAREST archive member — high means genuinely new.

    Nearest, not mean: a single near-duplicate is enough to make a candidate
    redundant, and averaging would hide that behind unrelated far members.
    """
    members = list(archive or [])[:int(limit)]
    if not members:
        return {"novelty": 1.0, "nearest_index": None, "n_archive": 0}
    best_d, best_i = None, None
    for i, m in enumerate(members):
        try:
            d = ncd(candidate, m)
        except Exception as exc:
            note_failure("exmachina:L327", exc)
            continue
        if best_d is None or d < best_d:
            best_d, best_i = d, i
    if best_d is None:
        return {"novelty": 1.0, "nearest_index": None, "n_archive": len(members)}
    return {"novelty": round(float(best_d), 4), "nearest_index": best_i,
            "n_archive": len(members)}

exmachina_operators:operator_report.seg:
def operator_report(rows: Sequence[dict], features: Optional[Sequence[str]] = None,
                    target: str = "margin", check: Optional[str] = None,
                    max_features: int = 6, max_cond: int = 1) -> Dict[str, Any]:
    """Exercise every operator organ against real rows, never raising.

    Each organ reports a MEASURED quantity (edges found, recall accuracy,
    routing entropy, holdout error) rather than a claim of readiness.

    `max_features`/`max_cond` are budgets, not preferences: PC conditions on
    every subset of a node's neighbours up to `max_cond`, so the test count
    grows combinatorially. Uncapped, RADIX on the fifteen auto-detected
    columns runs tens of thousands of partial-correlation solves and would
    stall a 30-second refresh loop.
    """
    out: Dict[str, Any] = {}
    keys = list(features or [])[:max(1, int(max_features))]
    needed = keys + ([target] if target else [])
    with_check = needed + ([check] if check else [])

    def _numeric(row: dict) -> Dict[str, float]:
        got: Dict[str, float] = {}
        for k, v in row.items():
            if isinstance(v, bool):
                continue
            try:
                f = float(v)
            except (TypeError, ValueError):
                note_failure("exmachina_operators:L1036", None)
                continue
            if math.isfinite(f):
                got[k] = f
        return got

    all_rows = [_numeric(r) for r in (rows or []) if isinstance(r, dict)]

    def _columns(req: Sequence[str]) -> Dict[str, List[float]]:
        """Column lists built ONLY from rows that carry every required key.

        Row alignment is the whole point. Building each column independently
        across a sparse field -- the check flag exists on 15 rows out of 120
        -- pairs one key's values with a DIFFERENT row's, so every
        correlation computed afterwards describes a dataset that never
        existed. Complete-case subsets are the honest alternative, and the
        count is reported rather than hidden.
        """
        cols: Dict[str, List[float]] = {k: [] for k in req}
        if not req:
            return cols
        for got in all_rows:
            if all(k in got for k in req):
                for k in req:
                    cols[k].append(got[k])
        return cols

    data = _columns(with_check)
    model_data = _columns(needed)
    n = min((len(v) for v in data.values()), default=0)
    n_models = min((len(v) for v in model_data.values()), default=0)
    out["n_rows"] = len(all_rows)
    out["n_complete"] = n
    out["n_complete_models"] = n_models

    # RADIX
    if keys and n >= 12:
        pairs = {k: v[:n] for k, v in data.items() if len(v) >= n}
        try:
            out["radix"] = discover(pairs, target=target if target in pairs else None,
                                    check=check if check in pairs else None,
                                    max_cond=max_cond)
        except Exception as exc:
            note_failure("exmachina_operators:L1078", exc)
            out["radix"] = {"error": "%s: %s" % (type(exc).__name__, exc)}
    else:
        out["radix"] = {"note": "need >=12 rows and >=1 numeric predictor"}

    # VELA
    try:
        hdc = HDC(dim=512)
        out["vela"] = hdc.selftest(n_items=24, n_queries=12)
    except Exception as exc:
        note_failure("exmachina_operators:L1087", exc)
        out["vela"] = {"error": "%s: %s" % (type(exc).__name__, exc)}

    # NEXUS + OPUS + NAVIS on the real series when there is enough of it.
    # These use the MODEL subset, not the RADIX subset: they do not need the
    # check column, and requiring it silently cut them from 120 rows to 15.
    if keys and n_models >= 16:
        nm = n_models
        X = [[model_data[k][i] for k in keys] for i in range(nm)]
        y = model_data.get(target, [0.0] * nm)[:nm]
        split = max(4, int(nm * 0.7))
        try:
            moe = SparseMoE(n_experts=min(4, len(keys) + 1), top_k=2).fit(X[:split], y[:split])
            pred = moe.predict(X[split:])
            err = [abs(pred[i] - y[split + i]) for i in range(len(pred))]
            moe_rep = moe.report(X)
            moe_rep["holdout_mae"] = round(sum(err) / len(err), 4) if err else None
            out["nexus"] = moe_rep
        except Exception as exc:
            note_failure("exmachina_operators:L1105", exc)
            out["nexus"] = {"error": "%s: %s" % (type(exc).__name__, exc)}
        try:
            kan = KAN(n_in=len(keys), n_grid=5).fit(X[:split], y[:split])
            kp = kan.predict(X[split:])
            kerr = [abs(kp[i] - y[split + i]) for i in range(len(kp))]
            krep = kan.report()
            krep["holdout_mae"] = round(sum(kerr) / len(kerr), 4) if kerr else None
            out["opus"] = krep
        except Exception as exc:
            note_failure("exmachina_operators:L1114", exc)
            out["opus"] = {"error": "%s: %s" % (type(exc).__name__, exc)}
        try:
            esn = EchoState(n_in=len(keys), n_res=32, seed=7)
            esn.fit(X[:split], y[:split], washout=2, ridge=1e-2)
            ep = esn.predict(X[split:], washout=2)
            eerr = [abs(ep[i] - y[split + i]) for i in range(min(len(ep), max(0, nm - split)))]
            out["navis"] = {"n_res": esn.n_res, "spectral_radius": esn.spectral_radius,
                            "trained": esn.readout is not None,
                            "holdout_mae": round(sum(eerr) / len(eerr), 4) if eerr else None}
        except Exception as exc:
            note_failure("exmachina_operators:L1124", exc)
            out["navis"] = {"error": "%s: %s" % (type(exc).__name__, exc)}
        try:
            bo = TrustRegionBO({k: (min(data[k]), max(data[k])) for k in keys})
            for i in range(min(split, 30)):
                bo.tell(X[i], y[i])
            out["catena"] = bo.report()
        except Exception as exc:
            note_failure("exmachina_operators:L1131", exc)
            out["catena"] = {"error": "%s: %s" % (type(exc).__name__, exc)}
    else:
        for k in ("nexus", "opus", "navis", "catena"):
            out[k] = {"note": "need >=16 rows and numeric predictors"}

    # LIMEN always available (it ranks whatever it is given)
    out["limen"] = {"items": 0, "note": "call rank_candidates() with the evidence set"}
    return out

federated:RewardShaperMeshWorm.local_sco.seg:
def local_score(self, rtt_ms: float = 50.0, fail_rate: float = 0.0,
                    size_kb: float = 100.0) -> dict[str, Any]:
        """Offline reward P(prefer | rtt, fail_rate, size) from task5 model.
        Falls back to the rtt/fail heuristic when the model file is missing."""
        import math as _math
        m = self._load_reward_model() or {}
        x = [min(2.0, rtt_ms / 2000.0), max(0.0, min(1.0, fail_rate)),
             min(1.0, size_kb / 5000.0)]
        if m.get("coef"):
            z = sum(c * v for c, v in zip(m["coef"], x)) + (m.get("intercept") or [0.0])[0]
            p = 1.0 / (1.0 + _math.exp(-z))
            src = "reward_model.json"
        else:
            p = 1.0 if (rtt_ms < 300 and fail_rate < 0.3) else 0.0
            src = "heuristic"
        return {"success": True, "reward": round(p, 4), "src": src,
                "features": {"rtt_ms": rtt_ms, "fail_rate": fail_rate, "size_kb": size_kb}}

glia:MicrogliaWorm.check_path.seg:
def check_path(self, path: str) -> dict[str, Any]:
        """3-sigma file-size anomaly check against task3 density model."""
        import os as _os
        try:
            size = _os.stat(path).st_size
        except OSError as exc:
            note_failure("glia:L118", exc)
            return {"success": False, "path": path, "error": str(exc)[:800]}
        model = self._load_density()
        # match by topdir name fragment, else global fallback
        entry = None
        for k, v in model.items():
            if k in path.replace("\\", "/"):
                entry = v
                break
        if entry is None and model:
            ns = [v for v in model.values() if v.get("n", 0) >= 100] or list(model.values())
            mu = sum(v["mean"] for v in ns) / len(ns)
            sd = max(1.0, sum(v["std"] for v in ns) / len(ns))
            entry = {"mean": mu, "std": sd, "n": sum(v["n"] for v in ns)}
        if entry is None:
            return {"success": True, "path": path, "anomaly": False, "src": "no-model"}
        z = abs(size - entry["mean"]) / max(1.0, entry["std"])
        return {"success": True, "path": path, "size": size,
                "z": round(z, 2), "anomaly": z > 3.0, "src": "size_density.json"}

learning_features:FeatureEngineer.impute.seg:
def impute_missing(self, values: List[Optional[float]], strategy: str = "mean") -> List[float]:
        """Impute missing (None) values."""
        valid = [v for v in values if v is not None]
        if not valid:
            return [0.0] * len(values)
        fill = sum(valid) / len(valid) if strategy == "mean" else sorted(valid)[len(valid) // 2]
        return [v if v is not None else fill for v in values]

learning_features:FeatureEngineer.one_ho.seg:
def one_hot_encode(self, categories: List[str], known_categories: Optional[List[str]] = None) -> Dict[str, Any]:
        """One-hot encode categorical variables."""
        cats = known_categories or sorted(set(categories))
        cat_to_idx = {c: i for i, c in enumerate(cats)}
        encoded = [[0] * len(cats) for _ in categories]
        for i, cat in enumerate(categories):
            if cat in cat_to_idx:
                encoded[i][cat_to_idx[cat]] = 1
        return {"categories": cats, "encoded": encoded}

learning_grpo:GRPOTrainer.replay_offline.seg:
def replay_offline_step(self, prefix: dict | None = None) -> dict:
        """Update the policy from a replayed prefix - no environment runs.

        Steps are grouped by context_key and each group goes through the
        ordinary update_policy, so the offline path reuses the live one
        rather than forking a second trainer whose gradient nothing compares.
        """
        if prefix is None:
            buffered = self.replay_batch(1)
            prefix = buffered[0] if buffered else None
        if not prefix:
            return {"updated": False, "reason": "no buffered prefix"}
        by_ctx: dict[str, list[dict]] = {}
        for step in prefix.get("steps", []) or []:
            by_ctx.setdefault(step.get("context_key", "default"), []).append(step)
        results = {}
        for ctx, steps in by_ctx.items():
            results[ctx] = self.update_policy(
                [s["worm"] for s in steps],
                [float(s.get("reward", 0.0)) for s in steps],
                context_key=ctx)
        return {"updated": True, "contexts": results,
                "n_steps": sum(len(s) for s in by_ctx.values())}

learning_pipeline:DataPipelineWorm.extra.seg:
def extract_field(self, field_name: str) -> Callable:
        """Create a transformation that extracts a field from each record."""
        def _extract(records):
            results = []
            for r in records:
                if isinstance(r, dict) and field_name in r:
                    val = r[field_name]
                    if isinstance(val, str):
                        try:
                            val = json.loads(val)
                        except (json.JSONDecodeError, TypeError):
                            note_failure("learning_pipeline:L199", None)
                    results.append(val)
            return results
        return _extract

def extract_recent(self, limit: int = 50, source: Optional[str] = None) -> List[Dict]:
        """Get most recent memories, optionally by source."""
        store = self._get_store()
        if not store:
            return []
        return store.recall_recent(limit=limit, source=source)

learning_pipeline:DataPipelineWorm.filte.seg:
def filter_by_severity(self, severity: str) -> Callable:
        """Create a transformation that filters records by severity."""
        def _filter(records):
            return [r for r in records if isinstance(r, dict) and r.get("severity") == severity]
        return _filter

def filter_by_source(self, source: str) -> Callable:
        """Create a transformation that filters records by source."""
        def _filter(records):
            return [r for r in records if isinstance(r, dict) and r.get("source") == source]
        return _filter

