learning_rl:RLTrainLoop.tune_history.seg:
def tune_history(self, limit: int = 20) -> Dict[str, Any]:
        """Query tune_config_registered events from LocalMemoryStore.

        Queries all 'tune_config_registered' events to show the
        progression of best_params and best scores over time.

        Args:
            limit: Max history entries to return.

        Returns:
            Dict with history list and summary stats.
        """
        try:
            from CORE.local_memory import get_memory_store
            store = get_memory_store()
            events = store.search_memories(
                "tune_config_registered", source="RLTrainLoop", limit=limit
            )

            history = []
            for ev in events:
                raw_data = ev.get("data", {})
                if isinstance(raw_data, str):
                    try:
                        data = json.loads(raw_data)
                    except Exception:  # noqa: BLE001 — skip malformed serialized payload
                        note_failure("learning_rl:L990", None)
                        continue
                else:
                    data = raw_data
                if isinstance(data, dict) and "best_params" in data:
                    history.append({
                        "registered_at": ev.get("timestamp", ""),
                        "best_params": data["best_params"],
                        "best_score": data.get("best_score"),
                        "n_configs_tried": data.get("n_configs_tried"),
                        "n_folds": data.get("n_folds"),
                        "data_source": data.get("data_source"),
                    })

            # Compute progression summary
            scores = [h["best_score"] for h in history if h["best_score"] is not None]

            return {
                "history": history,
                "count": len(history),
                "summary": {
                    "best_overall": max(scores) if scores else None,
                    "worst_overall": min(scores) if scores else None,
                    "avg_score": round(sum(scores) / len(scores), 4) if scores else None,
                    "n_tune_runs": len(history),
                } if scores else {},
            }
        except Exception as e:  # noqa: BLE001 — tuning failure returns signed error
            note_failure("learning_rl:L1017", e)
            return {"error": str(e), "history": []}

learning_versioner:pareto_retain.seg:
def pareto_retain(candidates, metrics_key="metrics"):
    """Pareto retention filter over version candidates (EP234, set half).

    candidates: [{..., metrics: {obj: float}}], all objectives maximized.
    Returns {"retained", "dominated"} (version strings). Wiring this into
    register_model as the retention predicate (collapsing EP228/EP234/EP462)
    stays deferred: admission policy needs coordinator approval.
    """
    vecs = {}
    for c in candidates or []:
        m = (c or {}).get(metrics_key, {}) or {}
        try:
            vecs[str(c.get("version", "?"))] = [float(v) for v in m.values()]
        except (TypeError, ValueError) as exc:
            note_failure("expansion/learning_versioner:253", exc)
            continue
    names = list(vecs)
    retained: list = []
    dominated: list = []
    for a in names:
        beaten = False
        for b in names:
            if a == b or len(vecs[b]) != len(vecs[a]) or not vecs[a]:
                continue
            if (all(y >= x for x, y in zip(vecs[a], vecs[b]))
                    and any(y > x for x, y in zip(vecs[a], vecs[b]))):
                beaten = True
                break
        (dominated if beaten else retained).append(a)
    return {"retained": retained, "dominated": dominated}

loom:NoveltyDrive.novelty_weight.seg:
def novelty_weight(self, base: float = 0.0, ceiling: float = 0.6) -> float:
        """Weight to add to a novelty term — capped so the drive cannot swamp fitness."""
        return float(min(ceiling, base + self.pressure * ceiling))

loom:descriptors_from_archive.seg:
def descriptors_from_archive(cells: Iterable[dict]) -> List[List[float]]:
    """Adapt QD archive cells into the descriptor point cloud Loom consumes.

    Accepts the archive's own shape (`descriptor` list, or `elite.cell`) so no
    new recording is needed.
    """
    out: List[List[float]] = []
    for c in cells:
        if not isinstance(c, dict):
            continue
        d = c.get("descriptor") or c.get("cell")
        if isinstance(d, (list, tuple)) and d:
            try:
                out.append([float(x) for x in d])
            except (TypeError, ValueError):
                note_failure("loom:L323", None)
                continue
    return out

meta_cognition:MetaCognitionWorm.compute.seg:
def compute_cross_worm_correlation(self, worm_types: (list[str] | None) = None,
                                       window_count: int = 20,
                                       min_correlation: float = 0.3) -> dict[str, Any]:
        """Compute error-rate correlation matrix across worm types.

        Detects if errors in one worm type predict errors in another.
        Uses rolling-window error rates and Pearson correlation.

        Args:
            worm_types: Specific worm types to compare, or None for all tracked
            window_count: Number of rolling windows to use for time series
            min_correlation: Minimum |r| to report as significant

        Returns:
            dict with correlation matrix, significant pairs, and recommendations
        """
        with self._lock:
            excluded = []
            if worm_types is None:
                worm_types = list(self._error_patterns.keys())
            else:
                excluded = [w for w in worm_types if w not in self._error_patterns]
                worm_types = [w for w in worm_types if w in self._error_patterns]

            if len(worm_types) < 2:
                return {
                    "correlations": [],
                    "message": "Need at least 2 worm types with error data",
                    "excluded_no_data": excluded,
                }

            # Build time-series of error rates for each worm type
            # Use the most recent observations to create rolling windows
            all_obs = self._observations[-500:]

        # Partition observations into time windows (include tail in last window)
        if len(all_obs) < window_count:
            return {"correlations": [], "total_analyzed": len(all_obs), "message": f"Insufficient data (need >= {window_count} windows)"}

        obs_per_window = max(1, len(all_obs) // window_count)
        windows = []
        for i in range(window_count - 1):
            windows.append(all_obs[i * obs_per_window: (i + 1) * obs_per_window])
        # Last window gets all remaining observations (avoids dropping tail)
        windows.append(all_obs[(window_count - 1) * obs_per_window:])

        # Compute error-rate time series per worm type
        worm_series: dict[str, list[float]] = {}
        for wt in worm_types:
            series = []
            for window in windows:
                wt_obs = [o for o in window if o["worm_type"] == wt]
                if wt_obs:
                    error_rate = sum(1 for o in wt_obs if o["outcome"] == "error") / len(wt_obs)
                else:
                    error_rate = 0.0
                series.append(error_rate)
            worm_series[wt] = series

        # Compute Pearson correlation for each pair
        def pearson_r(x: list[float], y: list[float]) -> float:
            n = len(x)
            if n < 3:
                return 0.0
            mean_x = sum(x) / n
            mean_y = sum(y) / n
            cov = sum((x[i] - mean_x) * (y[i] - mean_y) for i in range(n))
            std_x = (sum((xi - mean_x) ** 2 for xi in x)) ** 0.5
            std_y = (sum((yi - mean_y) ** 2 for yi in y)) ** 0.5
            if std_x == 0 or std_y == 0:
                return 0.0
            return cov / (std_x * std_y)

        correlations = []
        for i, wt_a in enumerate(worm_types):
            for wt_b in worm_types[i + 1:]:
                r = pearson_r(worm_series[wt_a], worm_series[wt_b])
                if abs(r) >= min_correlation:
                    direction = "positive" if r > 0 else "negative"
                    strength = ("strong" if abs(r) > 0.7 else "moderate" if abs(r) > 0.5 else "weak")
                    correlations.append({
                        "worm_a": wt_a,
                        "worm_b": wt_b,
                        "correlation": round(r, 4),
                        "direction": direction,
                        "strength": strength,
                        "interpretation": (
                            f"{wt_a} errors {'co-occur with' if r > 0 else 'are inversely related to'} {wt_b} errors"
                        ),
                    })

        # Sort by correlation magnitude
        correlations.sort(key=lambda c: -abs(c["correlation"]))

        # Generate recommendations from strong correlations
        recommendations = []
        for corr in correlations:
            if abs(corr["correlation"]) > 0.5:
                if corr["direction"] == "positive":
                    recommendations.append(
                        f"Consider joint CurativePool governance for {corr['worm_a']} and {corr['worm_b']} "
                        f"(r={corr['correlation']:.2f}) — errors propagate together"
                    )
                else:
                    recommendations.append(
                        f"Investigate inverse relationship between {corr['worm_a']} and {corr['worm_b']} "
                        f"(r={corr['correlation']:.2f}) — may indicate resource contention"
                    )

        return {
            "correlations": correlations,
            "significant_pairs": len(correlations),
            "worm_types_analyzed": len(worm_types),
            "total_windows": window_count,
            "min_correlation_threshold": min_correlation,
            "recommendations": recommendations,
            "timestamp": datetime.now().isoformat(),
        }

