def dispatch_cascade(self, task, run_fn, threshold: float = 0.65,
                         prompt_len: int = 100,
                         needs_vision: bool = False) -> dict[str, Any]:
        """Walk ranked experts, escalating while confidence < threshold.

        run_fn(expert_instance, task) -> (answer, confidence).
        Each attempt feeds feedback() (+1 ok / -1 fail) so the Q-table
        learns which expert handles what. Returns answer + trail.
        """
        ranked = self.dispatch(prompt_len, needs_vision).get("experts") or []
        trail: list[dict[str, Any]] = []
        best: dict[str, Any] | None = None
        for name in ranked:
            inst = self.get_expert(name)
            if inst is None:
                continue
            try:
                answer, conf = run_fn(inst, task)
                conf = 0.0 if conf is None else float(conf)
            except Exception as e:
                note_failure("synapse:L277", e)
                self.feedback(name, -1.0)
                trail.append({"expert": name, "error": str(e)[:800]})
                continue
            ok = conf >= float(threshold)
            self.feedback(name, 1.0 if ok else -0.5)
            trail.append({"expert": name, "confidence": round(conf, 3),
                          "accepted": ok})
            if ok:
                return {"success": True, "answer": answer, "via": name,
                        "escalations": len(trail) - 1, "trail": trail}
            if best is None or conf > best["confidence"]:
                best = {"expert": name, "answer": answer, "confidence": conf}
        if not trail:
            return {"success": False, "error": "no_resolvable_experts"}
        if best is None:
            # Every resolvable expert raised. The previous revision fell through
            # to a return that read `answer`, which is never bound on this path,
            # so the documented "best effort" outcome was an UnboundLocalError
            # (audit 2026-09-16, B6). A trial that produced no answer is a
            # failure, not a best effort.
            return {"success": False, "error": "all_experts_failed",
                    "escalations": len(trail) - 1, "trail": trail}
        # Below-threshold fallback reports the HIGHEST-confidence attempt, not
        # the last one tried: `name` after the loop is merely whichever expert
        # happened to be ranked last, which the old `best_effort_last_expert`
        # note asserted but did not deliver (B6, second half).
        return {"success": True, "answer": best["answer"],
                "via": best["expert"],
                "escalations": len(trail) - 1, "trail": trail,
                "below_threshold": round(best["confidence"], 3),
                "note": "best_effort_best_expert"}

telemetry:AlertEscalator.check_threshold.seg:
def check_threshold(self, name: str, value: float, warn: float, crit: float) -> (dict | None):
        """Check a value against thresholds and fire alert if needed."""
        dedup = f"{name}:{warn}:{crit}"
        if value >= crit and dedup not in self._fired:
            alert = {"name": name, "value": value, "severity": "CRITICAL", "threshold": crit, "time": datetime.now().isoformat()}
            with self._lock:
                self._fired.add(dedup)
                self._alerts.append(alert)
            return alert
        elif value >= warn:
            return {"name": name, "value": value, "severity": "WARNING", "threshold": warn}
        return None

telemetry:AlertEscalator.clear_alert.seg:
def clear_alert(self, name: str):
        with self._lock:
            to_remove = [k for k in self._fired if k.startswith(f"{name}:")]
            for k in to_remove:
                self._fired.discard(k)

telemetry:MetricAggregator.get_snapshot.seg:
def get_snapshot(self) -> dict[str, Any]:
        """Get Prometheus-style text snapshot."""
        with self._lock:
            return {
                "counters": dict(self._counters), "gauges": dict(self._gauges),
                "histograms": {k: {"count": len(v), "avg": round(sum(v) / len(v), 2) if v else 0,
                                   "p95": sorted(v)[int(len(v) * 0.95)] if v else 0} for k, v in self._histograms.items()},
            }

telemetry:MetricAggregator.inc_counter.seg:
def inc_counter(self, name: str, value: float = 1.0):
        with self._lock:
            self._counters[name] += value

telemetry:SpanTracer.end_span.seg:
def end_span(self, span_id: str, status: str = "ok") -> (dict | None):
        """End a trace span."""
        with self._lock:
            for s in self._spans:
                if s["id"] == span_id:
                    s["end_time"] = time.time()
                    s["duration_ms"] = round((s["end_time"] - s["start_time"]) * 1000, 2)
                    s["status"] = status
                    return s
        return None

telemetry:SpanTracer.get_trace_tree.seg:
def get_trace_tree(self) -> dict[str, Any]:
        """Get the trace as a tree structure."""
        with self._lock:
            return {"trace_id": self._trace_id, "span_count": len(self._spans), "spans": self._spans[-100:]}

telemetry:SpanTracer.start_span.seg:
def start_span(self, name: str, parent_id: str = "") -> dict[str, Any]:
        """Start a new trace span."""
        span = {
            "id": hashlib.sha256(f"{name}{time.time()}".encode()).hexdigest()[:16],
            "trace_id": self._trace_id, "name": name, "parent_id": parent_id,
            "start_time": time.time(), "end_time": None, "duration_ms": 0, "status": "running",
        }
        with self._lock:
            self._spans.append(span)
        return span

tensorgene:boruta_relevance.seg:
def boruta_relevance(history: Sequence[dict], fitness_key: str = "best_total",
                     min_rows: int = 20, max_iter: int = 30,
                     random_state: int = 7) -> Dict[str, Any]:
    """All-relevant gene ranking via Boruta (shadow-feature bake-off).

    Complements per-gene Spearman `usefulness`: correlation ranks genes one
    at a time and can crown a passenger that rides a driver's signal, while
    Boruta keeps EVERY gene that beats its own shuffled shadow — the right
    question for "which genes actually matter" on a small genome.

    Uses the same row conventions as `correlate` (payload unwrap, skip rows
    missing genes, dedupe identical vectors). Only genes present in >= half
    the usable rows enter the matrix (a gene trialled twice cannot beat
    noise honestly). Fail-open: Boruta missing, too few rows, or any error
    returns ok=False with a reason — never raises into the refresh cycle.
    """
    try:
        rows = []
        for row in history or ():
            data = row_payload(row)
            if data is None:
                continue
            genes = _gene_map(data)
            if not genes:
                continue
            try:
                fv = float(data.get(fitness_key))
            except (TypeError, ValueError):
                note_failure("tensorgene:L116", None)
                continue
            rows.append((genes, fv))
        if len(rows) < min_rows:
            return {"ok": False,
                    "reason": f"only {len(rows)} usable rows (< {min_rows})"}
        from collections import Counter
        present = Counter()
        for genes, _ in rows:
            present.update(k for k, v in genes.items()
                           if isinstance(v, (int, float)))
        keep = sorted(k for k, n in present.items() if n >= len(rows) // 2)
        if len(keep) < 2:
            return {"ok": False,
                    "reason": "fewer than 2 genes with majority coverage"}
        import numpy as np
        Xd_raw, yd_raw = [], []
        for genes, fv in rows:
            if all(isinstance(genes.get(k), (int, float)) for k in keep):
                Xd_raw.append([float(genes[k]) for k in keep])
                yd_raw.append(float(fv))
        if len(Xd_raw) < min_rows:
            return {"ok": False,
                    "reason": f"only {len(Xd_raw)} complete rows (< {min_rows})"}
        # Dedupe identical vectors (frozen-pool repeats are one measurement).
        seen, Xd, yd = set(), [], []
        for vec, fv in zip(Xd_raw, yd_raw):
            key = (tuple(round(v, 9) for v in vec), round(fv, 9))
            if key not in seen:
                seen.add(key)
                Xd.append(vec)
                yd.append(fv)
        if len(Xd) < min_rows:
            return {"ok": False,
                    "reason": f"only {len(Xd)} distinct rows (< {min_rows})"}
        from sklearn.ensemble import RandomForestRegressor
        from boruta import BorutaPy
        est = RandomForestRegressor(n_estimators=100, max_depth=5,
                                    random_state=random_state, n_jobs=1)
        selector = BorutaPy(est, n_estimators="auto", max_iter=max_iter,
                            random_state=random_state, verbose=0)
        selector.fit(np.array(Xd), np.array(yd))
        verdict = {}
        for k, rank, support, weak in zip(
                keep, selector.ranking_, selector.support_,
                selector.support_weak_):
            verdict[k] = ("confirmed" if support
                          else "tentative" if weak else "rejected")
        return {"ok": True, "genes": verdict, "n_rows": len(Xd),
                "n_estimators": int(getattr(selector, "n_estimators_", 0) or 0),
                "max_iter": int(max_iter)}
    except ImportError as exc:
        note_failure("tensorgene:L167", exc)
        return {"ok": False, "reason": f"missing dependency: {exc}"}
    except Exception as exc:
        note_failure("tensorgene:L169", exc)
        return {"ok": False, "reason": str(exc)[:160]}

