def hatch(self, egg_id: str) -> dict[str, Any]:
        with self._lock:
            egg = self._eggs.get(egg_id)
            if not egg:
                return {"success": False, "reason": "no_egg"}
            egg["hatched"] = True
            self._hatched += 1
            return {"success": True, "egg": egg_id, "hatched_total": self._hatched}

